code2='''def transform(grid):
    h, w = len(grid), len(grid[0])
    by_color = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 1:
                by_color.setdefault(value, set()).add((r, c))
    if 4 not in by_color:
        return [row[:] for row in grid]
    ref = by_color[4]
    r0 = min(r for r, c in ref)
    c0 = min(c for r, c in ref)
    shape = {(r-r0, c-c0) for r, c in ref}
    out = [row[:] for row in grid]

    for color, pixels in by_color.items():
        if color == 4:
            continue
        # Separate distant same-color objects, keeping fragments within two cells together.
        remaining = set(pixels)
        components = []
        while remaining:
            stack = [remaining.pop()]
            comp = set(stack)
            while stack:
                r, c = stack.pop()
                near = {(rr, cc) for rr, cc in remaining
                        if max(abs(rr-r), abs(cc-c)) <= 2}
                remaining.difference_update(near)
                comp.update(near)
                stack.extend(near)
            components.append(comp)
        for pts in components:
            anchors = set()
            for pr, pc in pts:
                for dr, dc in shape:
                    ar, ac = pr-dr, pc-dc
                    if all((r-ar, c-ac) in shape for r, c in pts):
                        anchors.add((ar, ac))
            if anchors:
                ar, ac = sorted(anchors)[0]
                for dr, dc in shape:
                    rr, cc = ar+dr, ac+dc
                    if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 1:
                        out[rr][cc] = color
    return out
